+fn verify_qe_identity_cert_chain(collateral: &Collateral, now: u64) -> Result<(), Error> {
+    let qe_identity_issuer_chain = &collateral.qe_identity_issuer_chain;
+    if qe_identity_issuer_chain.is_empty() {
+        return Err(Error::InvalidCertificateChain);
+    }
+
+    let certs = parse_pem_certs(qe_identity_issuer_chain)?;
+    if certs.len() < 2 {
+        return Err(Error::InvalidCertificateChain);
+    }
+
+    // Verify the certificate chain: each cert should be signed by the next
+    for i in 0..certs.len() - 1 {
+        let cert = &certs[i];
+        let issuer = &certs[i + 1];
+        verify_cert_signature(cert, issuer)?;
+        verify_cert_validity(cert, now)?;
+    }
+
+    // Verify the root certificate is self-signed
+    let root = &certs[certs.len() - 1];
+    verify_cert_signature(root, root)?;
+    verify_cert_validity(root, now)?;
+
+    // Verify root certificate is the Intel SGX Root CA
+    verify_intel_sgx_root_ca(root)?;
+
+    Ok(())
