+fn verify_qe_identity_signature(collateral: &Collateral) -> Result<(), Error> {
+    let qe_identity_issuer_chain = &collateral.qe_identity_issuer_chain;
+    let qe_identity = &collateral.qe_identity;
+    let qe_identity_signature = &collateral.qe_identity_signature;
+
+    if qe_identity_issuer_chain.is_empty() {
+        return Err(Error::InvalidCertificateChain);
+    }
+
+    // Parse the signing certificate (first cert in the issuer chain)
+    let certs = parse_pem_certs(qe_identity_issuer_chain)?;
+    if certs.is_empty() {
+        return Err(Error::InvalidCertificateChain);
+    }
+
+    let signing_cert = &certs[0];
+    let public_key = get_ecdsa_public_key(signing_cert)?;
+
+    // Decode the signature from hex
+    let sig_bytes = hex::decode(qe_identity_signature)
+        .map_err(|_| Error::InvalidSignature)?;
+
+    // The signature is over the raw QE Identity JSON body
+    let message = qe_identity.as_bytes();
+
+    // Verify ECDSA-P256-SHA256 signature
+    let peer_public_key = signature::UnparsedPublicKey::new(
+        &signature::ECDSA_P256_SHA256_ASN1,
+        &public_key,
+    );
