+<?php
+
+namespace MongoDB\Command;
+
+use MongoDB\Driver\Monitoring\CommandFailedEvent;
+use MongoDB\Driver\Monitoring\CommandStartedEvent;
+use MongoDB\Driver\Monitoring\CommandSucceededEvent;
+use MongoDB\Driver\Monitoring\CommandSubscriber as CommandSubscriberInterface;
+
+/**
+ * SensitiveCommandSubscriber wraps a CommandSubscriber and redacts
+ * security-sensitive command data from authentication-related commands
+ * before forwarding events to the wrapped subscriber.
+ */
+final class SensitiveCommandSubscriber implements CommandSubscriberInterface
+{
+    /** @var list<string> Commands whose payload should be redacted */
+    private static $sensitiveCommands = [
+        'authenticate',
+        'saslstart',
+        'saslcontinue',
+        'getnonce',
+        'createuser',
+        'updateuser',
+        'copydbgetnonce',
+        'copydbsaslstart',
+        'copydb',
+        'hello',
+        'ismaster',
+        'ismasterinternal',
+    ];
+
+    /** @var CommandSubscriberInterface */
+    private $subscriber;
+
+    public function __construct(CommandSubscriberInterface $subscriber)
+    {
+        $this->subscriber = $subscriber;
+    }
+
+    /**
+     * Determine if a command name is security-sensitive.
+     */
+    private static function isSensitiveCommand(string $commandName): bool
+    {
+        return in_array(strtolower($commandName), self::$sensitiveCommands, true);
+    }
+
+    public function commandStarted(CommandStartedEvent $event): void
+    {
+        $this->subscriber->commandStarted($event);
+    }
+
+    public function commandSucceeded(CommandSucceededEvent $event): void
+    {
+        $this->subscriber->commandSucceeded($event);
+    }
+
+    public function commandFailed(CommandFailedEvent $event): void
+    {
+        $this->subscriber->commandFailed($event);
