+/**
+ * Sanitize message content by removing platform-specific privileged tags
+ * that could be abused through injection (e.g., <qqbot-at-everyone />).
+ * @param {string} content - The raw message content
+ * @returns {string} - Sanitized message content
+ */
+function sanitizeMessage(content) {
+  if (typeof content !== 'string') return '';
+  let sanitized = content;
+  // Remove <qqbot-at-everyone> tags in all variations
+  sanitized = sanitized.replace(/<\/?qqbot-at-everyone\b[^>]*\/?>/gi, '');
+  return sanitized;
+}
+
+module.exports = { sanitizeMessage };

