+ * Uses the Function constructor with an explicit allowlist of context variables
+ * instead of eval, which would allow arbitrary code injection.
+ */
+export function evalInContext(script: string, context: any): any {
+    // Build a sandboxed function that only has access to explicitly provided context
+    const contextKeys = Object.keys(context);
+    const contextValues = contextKeys.map(key => context[key]);
+
+    // Block dangerous globals by shadowing them with undefined
+    const blockedGlobals = [
+        'process', 'require', 'child_process', 'execSync', 'exec',
+        'spawn', 'spawnSync', 'execFile', 'execFileSync', 'fork',
+        '__dirname', '__filename', 'module', 'exports',
+        'globalThis', 'global'
+    ];
+
+    const blockedParams = blockedGlobals.filter(g => !contextKeys.includes(g));
+    const blockedValues = blockedParams.map(() => undefined);
+
+    try {
+        const fn = new Function(
+            ...blockedParams,
+            ...contextKeys,
+            `"use strict"; return (async () => { ${script} })()`
+        );
+        return fn.call(context, ...blockedValues, ...contextValues);
+    } catch (e) {
+        throw new Error(`Dataview script execution error: ${e.message}`);
+    }
 }
