+/**
+ * Validates that a Content-Type / MIME type string contains only safe characters.
+ * This prevents code injection via maliciously crafted Content-Type headers.
+ *
+ * @param contentType - The Content-Type string to validate
+ * @returns true if the content type is safe, false otherwise
+ */
+export function isValidContentType(contentType: string): boolean {
+  if (!contentType || typeof contentType !== 'string') {
+    return false;
+  }
+  // Only allow characters that are valid in MIME types per RFC 2045
+  // type/subtype with optional parameters using safe characters
+  const SAFE_CONTENT_TYPE_PATTERN =
+    /^[a-zA-Z0-9][a-zA-Z0-9!#$&\-^_.+*/]*(?:\s*;\s*[a-zA-Z0-9\-_.]+\s*=\s*[a-zA-Z0-9\-_.+"' ]*)*$/;
+  return SAFE_CONTENT_TYPE_PATTERN.test(contentType);
+}
